const raw = $('Retell Tool Call').first().json.body || $('Retell Tool Call').first().json;
let args;
if (raw.arguments !== undefined) {
  args = typeof raw.arguments === 'string' ? JSON.parse(raw.arguments) : raw.arguments;
} else {
  args = raw;
}

const sede = args.sede;
const servicio = args.servicio;
const fecha = args.fecha;
const hora = args.hora;
const empleado = args.empleado || '';

// Location IDs
const LOCATION_IDS = {
