    { nombre: 'María', nombreNorm: 'maria', id: '968ca744f4a0356d6948ae097d54127b373c9cc5efcc889479381101773ee8e7@group.calendar.google.com' },
    { nombre: 'María2', nombreNorm: 'maria2', id: 'd70f48f63430635525a6ad0e7f835a32ae68a6e77aeb74810fd8ba9c4de836a2@group.calendar.google.com' },
    { nombre: 'Marian', nombreNorm: 'marian', id: '4cace839a6b98a4c7f5c910f4e898c1e0ebda5712c45939783b8e720543c9d5e@group.calendar.google.com' }
  ],
  'alpedrete': [
    { nombre: 'Ana', nombreNorm: 'ana', id: '7ced6d3e137d513c4cc58b517ad1fa344efbb883cdd3dbce8fd0046ac053c924@group.calendar.google.com' },
    { nombre: 'Cristina', nombreNorm: 'cristina', id: '62b7d9a94d9f7a745d1d7c65448838ceecaa5ab4e999e3ace21546c913f7a710@group.calendar.google.com' },
    { nombre: 'María', nombreNorm: 'maria', id: 'd70f48f63430635525a6ad0e7f835a32ae68a6e77aeb74810fd8ba9c4de836a2@group.calendar.google.com' }
  ]
};

// Tiempos de exposición por servicio
const TIEMPOS_EXPOSICION = {
  'Meches completas': { application: 45, exposure: 35, post: 10, total: 90 },
  'Meches tendencia': { application: 40, exposure: 40, post: 10, total: 90 },
  'Balayage': { application: 40, exposure: 40, post: 10, total: 90 },
  'Babylight': { application: 40, exposure: 40, post: 10, total: 90 },
  'Medias mechas': { application: 35, exposure: 35, post: 10, total: 80 },
  'Color Raíz': { application: 30, exposure: 25, post: 5, total: 60 },
  'Tinte raíz': { application: 30, exposure: 25, post: 5, total: 60 },
  'Baño de color orgánico': { application: 20, exposure: 35, post: 5, total: 60 },
  'Aplicación barros': { application: 40, exposure: 60, post: 10, total: 110 },
  'Tratamiento Keratina': { application: 40, exposure: 40, post: 10, total: 90 },
  'Tratamiento Antifrizz': { application: 60, exposure: 80, post: 20, total: 160 },
  'Alisado': { application: 60, exposure: 80, post: 20, total: 160 },
  'Permanente': { application: 40, exposure: 40, post: 10, total: 90 },
  'Desrizado frontal': { application: 20, exposure: 5, post: 5, total: 30 },
  'Tratamiento ligero intensivo': { application: 10, exposure: 5, post: 5, total: 20 },
  'Tratamiento premium': { application: 15, exposure: 10, post: 5, total: 30 },
  'Tratamiento slow repair': { application: 20, exposure: 20, post: 5, total: 45 },
  'Tratamiento détox cuero cabelludo': { application: 15, exposure: 10, post: 5, total: 30 },
  'Tratamiento détox mechas': { application: 15, exposure: 10, post: 5, total: 30 },
  'Tratamiento anticaída': { application: 10, exposure: 0, post: 5, total: 15 },
  'Manicura semipermanente': { application: 35, exposure: 5, post: 5, total: 45 },
  'Pedicura semipermanente': { application: 45, exposure: 10, post: 5, total: 60 },
  'Pedicura normal': { application: 40, exposure: 0, post: 5, total: 45 },
  'Tinte cejas': { application: 5, exposure: 3, post: 2, total: 10 },
  'Servicio Estrella': { application: 60, exposure: 45, post: 15, total: 120 }
};

// Duraciones simples
const DURACIONES_SIMPLES = {
  'Corte Señora': 45, 'Corte Caballero': 30, 'Corte flequillo': 10,
  'Corte niño/a': 20, 'Lavado + Secado': 20, 'Peinado': 30,
  'Difusor': 15, 'Quitar humedad': 5, 'Cejas': 15,
  'Depilación axilas': 10, 'Depilación brazos': 20, 'Depilación ingles': 15,
  'Depilación ingles integral': 20, 'Depilación piernas': 30, 'Depilación espalda': 30,
  'Manicura normal': 30, 'Entrecejo': 10, 'Labio': 10
};

// Obtener tiempos del servicio
let applicationMin, exposureMin, postMin, totalMin;
const tiempos = TIEMPOS_EXPOSICION[servicio];
if (tiempos) {
  applicationMin = tiempos.application;
  exposureMin = tiempos.exposure;
  postMin = tiempos.post;
  totalMin = tiempos.total;
} else {
  applicationMin = DURACIONES_SIMPLES[servicio] || 60;
  exposureMin = 0;
  postMin = 0;
  totalMin = applicationMin;
}

// Calcular fechas
const fechaInicio = new Date(`${fecha}T${hora}:00`);
const fechaFin = new Date(fechaInicio.getTime() + totalMin * 60000);
const finApplication = new Date(fechaInicio.getTime() + applicationMin * 60000);
const inicioPost = new Date(finApplication.getTime() + exposureMin * 60000);

const diasSemana = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
const meses = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
const diaSemana = diasSemana[fechaInicio.getUTCDay()];
const diaMes = fechaInicio.getUTCDate();
const mes = meses[fechaInicio.getUTCMonth()];

// Filtrar calendarios por empleado si se especifica
let calendariosSede = CALENDARIOS_POR_SEDE[sede] || CALENDARIOS_POR_SEDE['collado_villalba'];
if (empleado) {
  const empleadoNorm = empleado.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  calendariosSede = calendariosSede.filter(c => c.nombreNorm === empleadoNorm || empleadoNorm.includes(c.nombreNorm));
}

const locationId = LOCATION_IDS[sede] || LOCATION_IDS['collado_villalba'];

return [{ json: {
  sede,
  servicio,
  fecha,
  hora,
  empleado,
  location_id: locationId,
  calendarios_sede: calendariosSede,
  applicationMin,
  exposureMin,
  postMin,
  totalMin,
  fechaInicio: fechaInicio.toISOString(),
  fechaFin: fechaFin.toISOString(),
  finApplication: finApplication.toISOString(),
  inicioPost: inicioPost.toISOString(),
  fechaTexto: `${diaSemana} ${diaMes} de ${mes}`,
  horaFin: fechaFin.toISOString().split('T')[1].substring(0, 5),
  tiempo_activo_empleado: applicationMin + postMin
}}];

const parsedData = $('Parsear Argumentos').first().json;
const staffApiResult = $('Consultar Staff App (Turnos)').first();

const calendariosSede = parsedData.calendarios_sede;

function normalizarNombre(str) {
  return str.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
}

let calendariosFinales;
let staffAppUsada = false;
let empleadosDeTurno = [];

const apiOk = !staffApiResult.json.error && Array.isArray(staffApiResult.json);

if (apiOk && staffApiResult.json.length > 0) {
  staffAppUsada = true;
  empleadosDeTurno = staffApiResult.json.map(e => normalizarNombre(e.name || e.nombre || ''));

  calendariosFinales = calendariosSede.filter(cal => {
    const nombreNorm = normalizarNombre(cal.nombre);
    return empleadosDeTurno.some(turno =>
      turno === nombreNorm || turno.includes(nombreNorm) || nombreNorm.includes(turno)
    );
  });

  if (calendariosFinales.length === 0) {
    calendariosFinales = calendariosSede;
    staffAppUsada = false;
  }
} else {
  calendariosFinales = calendariosSede;
}

return [{ json: {
  ...parsedData,
  calendarios: calendariosFinales.map(c => c.id),
  empleados_activos: calendariosFinales.map(c => c.nombre),
  staff_app_usada: staffAppUsada,
  empleados_de_turno_raw: empleadosDeTurno
}}];

const data = $('Filtrar Empleados de Turno').first().json;
const calendarios = data.calendarios;
const fechaInicio = data.fechaInicio;
const fechaFin = data.fechaFin;

return calendarios.map(calId => ({
  json: {
    calendar_id: calId,
    fechaInicio,
    fechaFin,
    applicationMin: data.applicationMin,
    exposureMin: data.exposureMin,
    postMin: data.postMin,
    totalMin: data.totalMin,
    servicio: data.servicio,
    fecha: data.fecha,
    hora: data.hora
  }
}));

const input = $('Filtrar Empleados de Turno').first().json;
const resultados = $('Google Calendar - Consultar Hueco').all();

const newStart = new Date(input.fechaInicio);
const newEnd = new Date(input.fechaFin);

// Parsea los tiempos de exposición de la descripción de un evento existente.
// Los HH:MM en la descripción fueron escritos con .toISOString() → son UTC.
// Devuelve { finApplication, inicioPost } como fechas UTC, o null si no aplica.
function parsearTiemposExposicion(desc, eventoStart) {
  const exposureMatch = desc.match(/Empleado libre:\\s*(\\d+)\\s*min/);
  if (!exposureMatch) return null;
  const exposureMin = parseInt(exposureMatch[1]);
  if (exposureMin === 0) return null;

  const finAppMatch = desc.match(/Fin aplicaci[oó]n:\\s*(\\d{2}:\\d{2})/);
  const vuelveMatch = desc.match(/Vuelve empleado:\\s*(\\d{2}:\\d{2})/);
  if (!finAppMatch || !vuelveMatch) return null;

  const fechaUTC = eventoStart.toISOString().split('T')[0];
  return {
    finApplication: new Date(`${fechaUTC}T${finAppMatch[1]}:00Z`),
    inicioPost: new Date(`${fechaUTC}T${vuelveMatch[1]}:00Z`)
  };
}

// Función para verificar si un calendario tiene disponibilidad
function verificarCalendario(resultadoCalendario) {
  const eventos = resultadoCalendario.json || [];
  const eventosActivos = Array.isArray(eventos)
    ? eventos.filter(e => e.status !== 'cancelled')
    : [];

  // Si no hay eventos, el calendario está disponible
  if (eventosActivos.length === 0) return true;

  // Verificar cada evento para detectar conflictos
  for (const evento of eventosActivos) {
    const eventoStart = new Date(evento.start?.dateTime || evento.start?.date + 'T00:00:00Z');
    const eventoEnd = new Date(evento.end?.dateTime || evento.end?.date + 'T00:00:00Z');

    // Verificar si hay solapamiento entre la nueva cita y el evento existente
    const haySolapamiento = newStart < eventoEnd && newEnd > eventoStart;

    if (haySolapamiento) {
      // Hay solapamiento, verificar si la nueva cita cabe en el tiempo de exposición
      const desc = evento.description || '';
      const tiempos = parsearTiemposExposicion(desc, eventoStart);

      if (!tiempos) {
        // Sin información de exposición → conflicto real
        return false;
      }

      // Verificar si la nueva cita cabe COMPLETAMENTE dentro del tiempo libre
      const { finApplication, inicioPost } = tiempos;
      const cabeEnExposicion = newStart >= finApplication && newEnd <= inicioPost;

      if (!cabeEnExposicion) {
        // No cabe en la ventana libre → conflicto real
        return false;
      }
      // Si cabe en la exposición, continuar verificando otros eventos
    }
  }

  // Si llegamos aquí, ningún evento genera conflicto
  return true;
}

// Verificar cada calendario y contar los disponibles
const calendariosDisponibles = [];
const calendariosConflictivos = [];

resultados.forEach((resultado, index) => {
  const calendarioId = input.calendarios[index];
  const empleadoNombre = input.empleados_activos[index];

  if (verificarCalendario(resultado)) {
    calendariosDisponibles.push({
      calendario_id: calendarioId,
      empleado: empleadoNombre
    });
  } else {
    calendariosConflictivos.push({
      calendario_id: calendarioId,
      empleado: empleadoNombre
    });
  }
});

// Determinar respuesta final
if (calendariosDisponibles.length > 0) {
  // Hay al menos un empleado disponible
  return [{
    json: {
      disponible: true,
      fecha: input.fecha,
      hora: input.hora,
      horaFin: input.horaFin,
      servicio: input.servicio,
      sede: input.sede,
      empleados_libres: calendariosDisponibles.length,
      empleados_disponibles: calendariosDisponibles.map(e => e.empleado),
      empleados_conflictivos: calendariosConflictivos.map(e => e.empleado),
      empleados_consultados: input.empleados_activos,
      staff_app_usada: input.staff_app_usada,
      tiempos_servicio: {
        application_min: input.applicationMin,
        exposure_min: input.exposureMin,
        post_min: input.postMin,
        total_min: input.totalMin,
        tiempo_activo_empleado: input.applicationMin + input.postMin
      },
      mensaje: `Hay disponibilidad el ${input.fechaTexto} a las ${input.hora} en ${input.sede.replace('_', ' ')}. Empleados disponibles: ${calendariosDisponibles.map(e => e.empleado).join(', ')}`
    }
  }];
} else {
  // Ningún empleado disponible - buscar siguiente hueco
  const fechaInicio = new Date(input.fechaInicio);
  fechaInicio.setHours(fechaInicio.getHours() + 1);

  const diasSemana = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
  const meses = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
  const nuevaFecha = fechaInicio.toISOString().split('T')[0];
  const nuevaHora = fechaInicio.toISOString().split('T')[1].substring(0, 5);
  const diaSemana = diasSemana[fechaInicio.getUTCDay()];
  const diaMes = fechaInicio.getUTCDate();
  const mes = meses[fechaInicio.getUTCMonth()];

  return [{
    json: {
      disponible: false,
      empleados_consultados: input.empleados_consultados,
      empleados_conflictivos: calendariosConflictivos.map(e => e.empleado),
      staff_app_usada: input.staff_app_usada,
      tiempos_servicio: {
        application_min: input.applicationMin,
        exposure_min: input.exposureMin,
        post_min: input.postMin,
        total_min: input.totalMin,
        tiempo_activo_empleado: input.applicationMin + input.postMin
      },
      mensaje: `No hay disponibilidad a esa hora. El siguiente hueco es el ${diaSemana} ${diaMes} de ${mes} a las ${nuevaHora}`,
      siguiente_disponible: { fecha: nuevaFecha, hora: nuevaHora }
    }
  }];
}
